    // R2: shared atomic counter starting at zero.
    let counter = Arc::new(AtomicUsize::new(0));

    // R1: supervising task launches two worker threads.
    let mut handles = Vec::new();
    for _ in 0..2 {
        let counter = Arc::clone(&counter);
