            // compare_exchange makes each increment indivisible.
            loop {
                let current = counter.load(Ordering::SeqCst);
                let next = current + 1;
                if counter
                    .compare_exchange(current, next, Ordering::SeqCst, Ordering::SeqCst)
                    .is_ok()
                {
                    break;
